<div class="section-title"><div><h1>Manage users</h1><p class="muted">Disable accounts when necessary. Existing records are retained.</p></div></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Reports</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($users as $user):?><tr><td><?= h($user['name'])?><br><span class="muted"><?= h($user['email'])?></span></td><td><?= h(ucfirst($user['role']))?></td><td><?= (int)$user['report_count']?></td><td><?= status_badge($user['status'])?></td><td><?= h($user['created_at'])?></td><td><?php if((int)$user['id']!==(int)current_user()['id']):?><form method="post" class="inline-form"><?= csrf_field()?><input type="hidden" name="user_id" value="<?= (int)$user['id']?>"><input type="hidden" name="status" value="<?= $user['status']==='active'?'disabled':'active'?>"><button class="btn btn-small <?= $user['status']==='active'?'btn-danger':'btn-success'?>"><?= $user['status']==='active'?'Disable':'Enable'?></button></form><?php else:?><span class="muted">Current user</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
